package com.wylew.dates.util

import android.content.Context
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json
import java.io.InputStreamReader

/**
 * One entry of assets/segoe_svgs/metadata.json.
 * Generated by tools/build_segoe_metadata.py — rerun that instead of hand-editing.
 */
@Serializable
data class SvgMetadataEntry(
    val file: String,
    val name: String,
    val emoji: String = "",
    val category: String = "Symbols",
    val subcategory: String = "",
    val order: Int = Int.MAX_VALUE,
    val keywords: List<String> = emptyList()
)

data class SegoeSvgItem(
    val id: String,
    val name: String,
    val emoji: String,
    val fileUri: String,
    val filePath: String,
    val category: String,
    val subcategory: String,
    val order: Int,
    val keywords: List<String>
)

object SegoeSvgManager {
    private const val ASSET_DIR = "segoe_svgs"

    /** Standard Unicode emoji group order, as used by every system keyboard. */
    val CATEGORY_ORDER = listOf(
        "Smileys & Emotion",
        "People & Body",
        "Animals & Nature",
        "Food & Drink",
        "Travel & Places",
        "Activities",
        "Objects",
        "Symbols",
        "Flags"
    )

    @Volatile
    private var cache: List<SegoeSvgItem>? = null

    fun isPackDownloaded(context: Context): Boolean {
        return try {
            val list = context.assets.list(ASSET_DIR)
            !list.isNullOrEmpty()
        } catch (_: Exception) {
            false
        }
    }

    fun getDownloadedEmojis(context: Context): List<SegoeSvgItem> {
        cache?.let { return it }

        val metadataEntries = try {
            context.assets.open("$ASSET_DIR/metadata.json").use { inputStream ->
                InputStreamReader(inputStream).use { reader ->
                    val entries: List<SvgMetadataEntry> =
                        Json { ignoreUnknownKeys = true }.decodeFromString(reader.readText())
                    entries.associateBy { it.file }
                }
            }
        } catch (_: Exception) {
            emptyMap()
        }

        val assetFiles = try {
            context.assets.list(ASSET_DIR)?.filter { it.endsWith(".svg", ignoreCase = true) } ?: emptyList()
        } catch (_: Exception) {
            emptyList()
        }

        val items = assetFiles.map { fileName ->
            val metadata = metadataEntries[fileName]
            val base = fileName.removeSuffix(".svg")
            val assetUri = "file:///android_asset/$ASSET_DIR/$fileName"
            SegoeSvgItem(
                id = fileName,
                name = metadata?.name ?: base.replace("-", " ").replace("_", " ")
                    .replaceFirstChar { it.uppercase() },
                emoji = metadata?.emoji ?: "",
                fileUri = assetUri,
                filePath = assetUri,
                category = metadata?.category ?: "Symbols",
                subcategory = metadata?.subcategory ?: "",
                order = metadata?.order ?: Int.MAX_VALUE,
                keywords = metadata?.keywords ?: base.split("-", "_").map { it.lowercase() }
            )
        }.sortedWith(
            compareBy<SegoeSvgItem>(
                { CATEGORY_ORDER.indexOf(it.category).let { i -> if (i < 0) Int.MAX_VALUE else i } },
                { it.order },
                { it.name }
            )
        )
        cache = items
        return items
    }

    /** Categories that actually have items, in standard order. */
    fun categoriesFor(items: List<SegoeSvgItem>): List<String> {
        val present = items.mapTo(HashSet()) { it.category }
        return CATEGORY_ORDER.filter { it in present } + present.filter { it !in CATEGORY_ORDER }.sorted()
    }

    fun deletePack(_context: Context) {
        // No-op for bundled assets
    }
}
